	6616: {
		names: [{ nominative: "Holy Righteous John, Wonderworker of Kronstadt and All Russia (ROCOR)", short: "St John" }],
		biographies: [],
		info: [],
		refs: [],
		services: [
			{
				type: "4",
				hymns: [],
				sections: [
					{
						section: "vespers",
						items: [
							{ kind: "scripture", type: "1", reading: "Joel_2:12-26" },
							{ kind: "scripture", type: "2", reading: "Joel_2:27-32" },
							{ kind: "scripture", type: "3", reading: "I Jn_4:20-5:5" },
						],
					},
					{
						section: "matins",
						items: [{ kind: "scripture", type: "1", reading: "Lk_6:17-23", pericope: "24", cmd: "dow != 0" }],
					},
					{
						section: "liturgy",
						items: [
							{
								kind: "troparion",
								text: "With the apostles thy sound hath gone forth into all the earth; * with the confessors thou didst endure sufferings for Christ; * thou didst resemble the holy hierarchs in thy preaching of the Word; * and with the venerable hast thou shone forth in the grace of God. * Therefore, the Lord hath exalted the depths of thy humility above the heavens, * and hath given us thy name as a source of most wondrous miracles. * Wherefore, O wonderworker, who livest in Christ forever, * take pity in thy love upon people in misfortunes; * and hearken unto thy children, * who with faith call upon thee, ** O righteous John, our beloved pastor.",
								type: "1",
								tone: "4",
							},
							{
								kind: "troparion",
								text: "O wonderworker, who livest in Christ forever, * take pity in thy love upon people in misfortunes; * hearken unto thy children who with faith call upon thee, * expecting compassionate aid from thee, ** O John of Kronstadt, our beloved pastor.",
								type: "2",
								tone: "4",
							},
							{
								kind: "kontakion",
								text: "O father John, namesake of grace, who wast chosen by God from childhood, who in thy youth miraculously received from Him the gift of learning, and in a dream wast most gloriously called to be a priest: Entreat Christ God, that we may all be with thee in the kingdom of heaven.",
								type: "1",
								tone: "4",
							},
						],
					},
				],
			},
		],
		hymns: [],
	},
